import{_ as t,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const l=JSON.parse('{"title":"Product Review","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/product-reviews/index.md","filePath":"api/rest-api/shop/product-reviews/index.md","lastUpdated":1787290888000}'),i={name:"api/rest-api/shop/product-reviews/index.md"};function d(s,e,n,c,h,p){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="product-review" tabindex="-1">Product Review <a class="header-anchor" href="#product-review" aria-label="Permalink to &quot;Product Review&quot;">​</a></h1><p>The Product Review menu covers the ratings and reviews shoppers leave on products. Anyone can read the reviews on a product; a logged-in customer can write a new review and edit or delete their own.</p><h2 id="read-vs-write" tabindex="-1">Read vs. write <a class="header-anchor" href="#read-vs-write" aria-label="Permalink to &quot;Read vs. write&quot;">​</a></h2><p>Reading is public — a storefront key is enough for both the per-product listing and a single review by ID. Writing requires a customer Bearer token unless the store has guest reviews switched on, and a review can only be edited or deleted by the customer who wrote it.</p><p>Two store settings gate submission: customer reviews can be switched off entirely, and guest reviews separately. Both are enforced on the API, so a form should not be shown when the store has reviews disabled.</p><p>New reviews are stored as <code>pending</code> and are excluded from the default product listing until an admin approves them. A single review fetched by ID is returned whatever its status.</p><h2 id="review-lifecycle" tabindex="-1">Review Lifecycle <a class="header-anchor" href="#review-lifecycle" aria-label="Permalink to &quot;Review Lifecycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Where it shows</th></tr></thead><tbody><tr><td><code>pending</code></td><td>Just submitted, awaiting moderation</td><td>Absent from the default product listing; readable by id, or with <code>?status=pending</code></td></tr><tr><td><code>approved</code></td><td>Published by an admin</td><td>The default listing</td></tr><tr><td><code>disapproved</code></td><td>Reviewed and rejected</td><td>Only with <code>?status=disapproved</code></td></tr></tbody></table><p>The status is <code>disapproved</code>, not &quot;rejected&quot;. Editing an approved review does <strong>not</strong> send it back for moderation — the text changes and the review stays live.</p><h2 id="reading-reviews" tabindex="-1">Reading Reviews <a class="header-anchor" href="#reading-reviews" aria-label="Permalink to &quot;Reading Reviews&quot;">​</a></h2><p>The per-product listing defaults to approved only, and takes one <code>status</code> value plus one <code>rating</code> at a time; combining them narrows further. Rows come back oldest-first by id, with no sort parameter, so a &quot;most recent&quot; widget has to request the last page or reverse the array. The count is in <code>X-Total-Count</code>, since the body is one page of up to 50.</p><p>There is no aggregate endpoint — no average rating, no per-star counts. A rating histogram means one call per star value, reading <code>X-Total-Count</code> off each.</p><h2 id="writing-a-review" tabindex="-1">Writing a Review <a class="header-anchor" href="#writing-a-review" aria-label="Permalink to &quot;Writing a Review&quot;">​</a></h2><p>The write routes do not sit under the product: creating is <code>POST /api/shop/reviews</code> with <code>productId</code> <strong>in the body</strong>, and editing and deleting address <code>/api/shop/reviews/{id}</code>. Updating is <code>PATCH</code> with <code>Content-Type: application/merge-patch+json</code> — plain <code>application/json</code> is refused with <code>415</code>, and <code>PUT</code> is not routed at all.</p><p><code>title</code>, <code>comment</code>, <code>rating</code> (1–5) and <code>productId</code> are required on create; <code>name</code> is optional but is <strong>not</strong> filled in from the customer&#39;s profile, so a review submitted without it displays with an empty author.</p><p>Nothing prevents the same customer reviewing the same product twice — enforce a one-review rule client-side if the store wants one.</p><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><p>A review may only be edited or removed by the customer who wrote it, checked against the stored author rather than the token alone. Another customer&#39;s review answers <code>403</code>, and a review submitted by a guest carries no author, so it can never be changed once submitted.</p><h2 id="the-customer-s-own-reviews" tabindex="-1">The Customer&#39;s Own Reviews <a class="header-anchor" href="#the-customer-s-own-reviews" aria-label="Permalink to &quot;The Customer&#39;s Own Reviews&quot;">​</a></h2><p>A shopper&#39;s review history is a separate menu — <a href="/api/rest-api/shop/customer-reviews/get-customer-reviews.html">Customer Reviews</a> — and unlike this one it applies no status filter, which is what lets a customer see their own pending submission.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/product-reviews/get-product-reviews.html">Get Product Reviews</a></td><td><code>GET /api/shop/products/{id}/reviews</code></td><td>List a product&#39;s reviews. Approved only unless <code>?status=</code> says otherwise.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/get-product-review.html">Get Product Review</a></td><td><code>GET /api/shop/reviews/{id}</code></td><td>A single review by ID, any status.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a></td><td><code>POST /api/shop/reviews</code></td><td>Submit a review. The product goes in the body, not the path.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/update-product-review.html">Update Product Review</a></td><td><code>PATCH /api/shop/reviews/{id}</code></td><td>Edit the customer&#39;s own review. Requires <code>application/merge-patch+json</code>.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/delete-product-review.html">Delete Product Review</a></td><td><code>DELETE /api/shop/reviews/{id}</code></td><td>Remove the customer&#39;s own review.</td></tr></tbody></table><p>There is also <code>GET /api/shop/reviews</code>, a flat listing across all products, subject to the same approved-only default.</p><p>Read endpoints need only the storefront key; create, update and delete require a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',24)]))}const w=t(i,[["render",d]]);export{l as __pageData,w as default};
